values
  ('ef1d4b84-5c8c-49eb-a8ca-c21694fda7f4', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', null, 'topic'::public.curated_course_node_type, 'Page Layout as Editorial Communication and Publication Systems', 'This opening unit frames page layout as communication design, not merely software operation. Students learn how editorial intent, audience, sequence, hierarchy, and production context shape every page decision.', 0),
  ('35408ba3-4914-4317-ae1d-9aa86980f0d5', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', 'ef1d4b84-5c8c-49eb-a8ca-c21694fda7f4', 'subtopic'::public.curated_course_node_type, 'Editorial purpose and audience', 'Students learn to translate content goals into layout choices that make reading purposeful, credible, and visually memorable.', 0),
