  ('1545dcb5-246c-42e6-b243-0e8e42535f16', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', 'ef1d4b84-5c8c-49eb-a8ca-c21694fda7f4', 'subtopic'::public.curated_course_node_type, 'Visual communication ethics', 'Layout can clarify, persuade, include, or mislead; this subtopic establishes responsible design habits early.', 2),
