  ('8cd969d3-73ba-4b12-a91c-5a3e185a1cfb', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', '1545dcb5-246c-42e6-b243-0e8e42535f16', 'concept'::public.curated_course_node_type, 'inclusive representation', null, 3),
  ('42cf3747-d8a0-4fbf-b942-ef83c6e4f9c0', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', null, 'topic'::public.curated_course_node_type, 'InDesign Workspace, File Structure, and Professional Workflow', 'Students build confidence in the InDesign environment while learning the file habits used in studios, agencies, publishers, and in-house creative teams.', 1),
  ('42f56fe4-86b5-4853-a788-82248dbfe135', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', '42cf3747-d8a0-4fbf-b942-ef83c6e4f9c0', 'subtopic'::public.curated_course_node_type, 'Workspace fluency', 'Students learn where tools live, how panels work, and how to customize the interface so production decisions stay fast and accurate.', 0),
