  ('0a1d2a76-87d3-4420-a6be-7f2c8e02e887', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', '42f56fe4-86b5-4853-a788-82248dbfe135', 'concept'::public.curated_course_node_type, 'shortcuts and command search', null, 3),
  ('e47810dc-3759-485f-8744-c3d5aea5bc03', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', '42cf3747-d8a0-4fbf-b942-ef83c6e4f9c0', 'subtopic'::public.curated_course_node_type, 'Document and project organization', 'A good layout file is supported by clean folders, linked assets, naming conventions, and predictable exports.', 1),
  ('b8558be4-8e68-43d5-9d96-44bd20d39731', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', 'e47810dc-3759-485f-8744-c3d5aea5bc03', 'concept'::public.curated_course_node_type, 'folder structures', null, 0),
