  ('46cb18d4-0ba6-43b9-a37f-c30adeffb6c9', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', 'e47810dc-3759-485f-8744-c3d5aea5bc03', 'concept'::public.curated_course_node_type, 'asset checklists', null, 3),
  ('62be3943-365c-4bb8-8dcf-97577c95963d', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', '42cf3747-d8a0-4fbf-b942-ef83c6e4f9c0', 'subtopic'::public.curated_course_node_type, 'Cross-app workflow', 'InDesign often depends on Photoshop, Illustrator, Acrobat, and font services, so students learn how assets move across the Adobe ecosystem.', 2),
  ('3fb741c5-20d9-4d8a-adbf-04cb57eb4767', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', '62be3943-365c-4bb8-8dcf-97577c95963d', 'concept'::public.curated_course_node_type, 'PSD, AI, SVG, PDF, and image formats', null, 0),
  ('7cb6cf95-6996-498d-ba74-694585390cfd', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', '62be3943-365c-4bb8-8dcf-97577c95963d', 'concept'::public.curated_course_node_type, 'linked versus embedded assets', null, 1),
  ('10cbb722-4ca6-4426-8d03-2027e6c99d11', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', '62be3943-365c-4bb8-8dcf-97577c95963d', 'concept'::public.curated_course_node_type, 'Creative Cloud Libraries', null, 2),
  ('7408e126-0ccd-408f-b8ba-fe3f492d424a', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', '62be3943-365c-4bb8-8dcf-97577c95963d', 'concept'::public.curated_course_node_type, 'handoff to Acrobat and print vendors', null, 3),
  ('fa47fa6a-3cb1-4a9c-8a70-40c8e8c09123', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', null, 'topic'::public.curated_course_node_type, 'Document Setup: Pages, Spreads, Bleeds, Margins, and Columns', 'This unit teaches students to set up a document correctly before designing, preventing common production failures and helping layouts feel intentional from the first page.', 2),
  ('ff072bfd-0b36-465e-a7ac-dabdbbe7f79e', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', 'fa47fa6a-3cb1-4a9c-8a70-40c8e8c09123', 'subtopic'::public.curated_course_node_type, 'Page formats and publication specs', 'Students learn how physical and digital formats affect page size, orientation, spread behavior, and output planning.', 0),
  ('cf202b92-f6f4-4eea-b940-a246aed56174', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', 'ff072bfd-0b36-465e-a7ac-dabdbbe7f79e', 'concept'::public.curated_course_node_type, 'trim size and orientation', null, 0),
