  ('2496e619-b944-42f4-8738-956b7224bb37', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', 'fa47fa6a-3cb1-4a9c-8a70-40c8e8c09123', 'subtopic'::public.curated_course_node_type, 'Margins, columns, and baseline grids', 'Students use structural guides to turn content into readable systems with strong alignment and rhythm.', 1),
