  ('36d14336-31e3-4d1f-a7c5-b1ef7b085cd3', 'a9b0c1d2-3e4f-4a77-8c67-7d8e9f0a1b47', null, 'topic'::public.curated_course_node_type, 'Grids, Guides, Modular Systems, and Spatial Hierarchy', 'Grid systems turn pages into organized fields. Students learn when to follow a grid, when to bend it, and how hierarchy emerges from structure.', 3),
