update public.learning_paths
set
  title = 'Page Layout (InDesign)',
  goal = 'Page Layout (InDesign)',
  summary = 'Page Layout (InDesign) develops the technical, visual, and production judgment required to design professional publications for print and digital delivery. Students learn InDesign through editorial design problems: grids, typography, multi-page systems, image placement, styles, parent pages, tables, preflight, packaging, accessible exports, and critique-driven revision. The course culminates in a polished publication system that can function as a portfolio case study.',
  data = $pagljson${"slug": "page-layout-indesign", "title": "Page Layout (InDesign)", "description": "Page Layout (InDesign) develops the technical, visual, and production judgment required to design professional publications for print and digital delivery. Students learn InDesign through editorial design problems: grids, typography, multi-page systems, image placement, styles, parent pages, tables, preflight, packaging, accessible exports, and critique-driven revision. The course culminates in a polished publication system that can function as a portfolio case study.", "topics": [{"id": "ef1d4b84-5c8c-49eb-a8ca-c21694fda7f4", "type": "topic", "title": "Page Layout as Editorial Communication and Publication Systems", "description": "This opening unit frames page layout as communication design, not merely software operation. Students learn how editorial intent, audience, sequence, hierarchy, and production context shape every page decision.", "children": [{"id": "35408ba3-4914-4317-ae1d-9aa86980f0d5", "type": "subtopic", "title": "Editorial purpose and audience", "children": [{"id": "6fc700a4-1c04-4813-bdcd-1333403e672d", "type": "concept", "title": "reader needs and publication goals"}, {"id": "b2d062dd-e3a0-447f-8ddf-9b66adce3def", "type": "concept", "title": "tone, genre, and brand voice"}, {"id": "46971df6-f94c-4303-bd53-55f6d0ebd9b1", "type": "concept", "title": "editorial hierarchy and sequencing"}, {"id": "0a0a7195-2bdb-48fc-a994-c62f998b30f3", "type": "concept", "title": "content audits and page inventories"}], "description": "Students learn to translate content goals into layout choices that make reading purposeful, credible, and visually memorable."}, {"id": "40a37444-0cdf-47cc-836e-0c269decd632", "type": "subtopic", "title": "Publication systems thinking", "children": [{"id": "da84c483-0883-4fa6-a52b-0752ce33aa82", "type": "concept", "title": "recurring page types"}, {"id": "4e6cb01e-b61a-4448-8e71-d7106bd20c12", "type": "concept", "title": "section rhythm"}, {"id": "c34d7ac9-2719-4fd8-8ba9-26bb6e89851c", "type": "concept", "title": "template logic"}, {"id": "0a1245a4-8f32-4608-9c54-2b7b28dee2f1", "type": "concept", "title": "cross-document consistency"}], "description": "The goal is to see a brochure, report, magazine, or book as a repeatable system rather than a set of isolated pages."}, {"id": "1545dcb5-246c-42e6-b243-0e8e42535f16", "type": "subtopic", "title": "Visual communication ethics", "children": [{"id": "d46d233e-d733-4a14-ad69-45ead809c403", "type": "concept", "title": "legibility and accessibility"}, {"id": "edbe0fa8-96d4-436e-8f24-464c2c3daaa7", "type": "concept", "title": "image context and captions"}, {"id": "19b657bb-6747-48aa-8746-61f756c4bf5e", "type": "concept", "title": "data and quote integrity"}, {"id": "8cd969d3-73ba-4b12-a91c-5a3e185a1cfb", "type": "concept", "title": "inclusive representation"}], "description": "Layout can clarify, persuade, include, or mislead; this subtopic establishes responsible design habits early."}]}, {"id": "42cf3747-d8a0-4fbf-b942-ef83c6e4f9c0", "type": "topic", "title": "InDesign Workspace, File Structure, and Professional Workflow", "description": "Students build confidence in the InDesign environment while learning the file habits used in studios, agencies, publishers, and in-house creative teams.", "children": [{"id": "42f56fe4-86b5-4853-a788-82248dbfe135", "type": "subtopic", "title": "Workspace fluency", "children": [{"id": "221c971f-4a06-452e-9947-f8df94b662b2", "type": "concept", "title": "tools, panels, and control bar"}, {"id": "ef498f0d-2458-4c8c-9126-87f57e5c20fc", "type": "concept", "title": "workspace presets"}, {"id": "f1a673ee-6134-4856-ba23-256322569197", "type": "concept", "title": "rulers, guides, and smart guides"}, {"id": "0a1d2a76-87d3-4420-a6be-7f2c8e02e887", "type": "concept", "title": "shortcuts and command search"}], "description": "Students learn where tools live, how panels work, and how to customize the interface so production decisions stay fast and accurate."}, {"id": "e47810dc-3759-485f-8744-c3d5aea5bc03", "type": "subtopic", "title": "Document and project organization", "children": [{"id": "b8558be4-8e68-43d5-9d96-44bd20d39731", "type": "concept", "title": "folder structures"}, {"id": "4770e82c-8d76-400a-8cc5-8eb9fbf0fbb8", "type": "concept", "title": "naming and versioning"}, {"id": "183c29eb-ec4f-45c3-8888-5b780d6e0ba1", "type": "concept", "title": "links and fonts folders"}, {"id": "46cb18d4-0ba6-43b9-a37f-c30adeffb6c9", "type": "concept", "title": "asset checklists"}], "description": "A good layout file is supported by clean folders, linked assets, naming conventions, and predictable exports."}, {"id": "62be3943-365c-4bb8-8dcf-97577c95963d", "type": "subtopic", "title": "Cross-app workflow", "children": [{"id": "3fb741c5-20d9-4d8a-adbf-04cb57eb4767", "type": "concept", "title": "PSD, AI, SVG, PDF, and image formats"}, {"id": "7cb6cf95-6996-498d-ba74-694585390cfd", "type": "concept", "title": "linked versus embedded assets"}, {"id": "10cbb722-4ca6-4426-8d03-2027e6c99d11", "type": "concept", "title": "Creative Cloud Libraries"}, {"id": "7408e126-0ccd-408f-b8ba-fe3f492d424a", "type": "concept", "title": "handoff to Acrobat and print vendors"}], "description": "InDesign often depends on Photoshop, Illustrator, Acrobat, and font services, so students learn how assets move across the Adobe ecosystem."}]}, {"id": "fa47fa6a-3cb1-4a9c-8a70-40c8e8c09123", "type": "topic", "title": "Document Setup: Pages, Spreads, Bleeds, Margins, and Columns", "description": "This unit teaches students to set up a document correctly before designing, preventing common production failures and helping layouts feel intentional from the first page.", "children": [{"id": "ff072bfd-0b36-465e-a7ac-dabdbbe7f79e", "type": "subtopic", "title": "Page formats and publication specs", "children": [{"id": "cf202b92-f6f4-4eea-b940-a246aed56174", "type": "concept", "title": "trim size and orientation"}, {"id": "3b0b279e-8890-4917-9c06-c8a091d91f3f", "type": "concept", "title": "facing pages and spreads"}, {"id": "26af445c-acc1-4bcd-94ea-e1ca4fbf4023", "type": "concept", "title": "slug, bleed, and safe area"}, {"id": "11661174-1630-44d9-868d-4845ce8cd75f", "type": "concept", "title": "print versus screen dimensions"}], "description": "Students learn how physical and digital formats affect page size, orientation, spread behavior, and output planning."}, {"id": "2496e619-b944-42f4-8738-956b7224bb37", "type": "subtopic", "title": "Margins, columns, and baseline grids", "children": [{"id": "be72a9d9-f093-41e7-b957-a07d4e51ff37", "type": "concept", "title": "margin systems"}, {"id": "020db851-e9f9-4201-a38a-0052d3323459", "type": "concept", "title": "column count and gutters"}, {"id": "933e5d1f-7abd-4700-9ac3-cf8892481dd5", "type": "concept", "title": "baseline grid setup"}, {"id": "474626c4-90f9-405b-b45a-34550507cdc0", "type": "concept", "title": "modular spacing units"}], "description": "Students use structural guides to turn content into readable systems with strong alignment and rhythm."}, {"id": "845ecefa-a9a1-4549-a5e8-672303de9b99", "type": "subtopic", "title": "Document presets and templates", "children": [{"id": "0f2eea28-bafe-48e2-9023-2393ebf3521e", "type": "concept", "title": "custom presets"}, {"id": "7167590d-03a0-4531-b688-0a1b2c3e94e3", "type": "concept", "title": "template files"}, {"id": "b63bb2ff-4ed7-45b2-882f-a27d14951af7", "type": "concept", "title": "page count planning"}, {"id": "7db62728-208f-4abd-a4d7-5548360c1281", "type": "concept", "title": "default styles and swatches"}], "description": "Students learn to save setup decisions so future projects begin with reliable production foundations."}]}, {"id": "36d14336-31e3-4d1f-a7c5-b1ef7b085cd3", "type": "topic", "title": "Grids, Guides, Modular Systems, and Spatial Hierarchy", "description": "Grid systems turn pages into organized fields. Students learn when to follow a grid, when to bend it, and how hierarchy emerges from structure.", "children": [{"id": "9c6c3d9a-1a91-4142-a316-c2ef4da92e27", "type": "subtopic", "title": "Classical and modern grid systems", "children": [{"id": "e9258a1c-b097-45cb-bcf3-98683f18d834", "type": "concept", "title": "manuscript grids"}, {"id": "3e26ad38-01c0-40ac-a0aa-a90fd5d05b20", "type": "concept", "title": "column grids"}, {"id": "23d6b8d9-5d35-40be-a4c5-dd579cb0cc12", "type": "concept", "title": "modular grids"}, {"id": "1dcee48e-b5ad-4f4a-a7f2-543bc1afa2c9", "type": "concept", "title": "Swiss and contemporary grid traditions"}], "description": "Students study single-column, multicolumn, modular, manuscript, and asymmetric grids as tools for clarity and variation."}, {"id": "cf82c936-cbc1-4720-b831-f450f96675b1", "type": "subtopic", "title": "Hierarchy through space", "children": [{"id": "f3a254bc-34f5-481c-9322-a30524f167ec", "type": "concept", "title": "visual entry points"}, {"id": "3dd4314d-dc5d-49ff-b772-73d56e94b262", "type": "concept", "title": "proximity and grouping"}, {"id": "c438ed21-71ea-4840-b2af-34fd6772441f", "type": "concept", "title": "white space as structure"}, {"id": "3efcb160-a676-41ef-a8ba-7b349f727c1e", "type": "concept", "title": "rhythm across spreads"}], "description": "Students learn to use scale, grouping, whitespace, and alignment to signal what matters first, second, and third."}, {"id": "ec163234-8d9f-4884-be27-0bc72ac562b4", "type": "subtopic", "title": "Breaking the grid", "children": [{"id": "73542f62-4a91-4776-aa41-90d5e533d187", "type": "concept", "title": "intentional asymmetry"}, {"id": "2e65ea9d-cfa2-40c5-a56a-6033fc39d7c8", "type": "concept", "title": "overlap and layering"}, {"id": "930ea286-35d9-4534-b491-5643c6d13e58", "type": "concept", "title": "scale contrast"}, {"id": "f3bb88df-9cbf-4a69-9f66-38be5588f3d2", "type": "concept", "title": "editorial pacing"}], "description": "Students practice controlled disruption so expressive pages remain readable and purposeful."}]}, {"id": "901a99a2-de73-46e4-9654-c6ef6186cb5c", "type": "topic", "title": "Text Frames, Image Frames, Linking, Fitting, and Layout Objects", "description": "This unit moves from setup into page construction. Students learn the core mechanics of building layouts with text, image, and object frames.", "children": [{"id": "7c2aa40c-8230-4dd1-990e-2f5257e6673a", "type": "subtopic", "title": "Text frame control", "children": [{"id": "bb23b6cc-780b-46cf-a2c3-21302b3a120a", "type": "concept", "title": "threaded text"}, {"id": "8f74ccc4-d205-402e-8706-c137d51cd38f", "type": "concept", "title": "inset spacing"}, {"id": "066477c6-ee1c-48e7-a7c0-7d4e6aaca4a9", "type": "concept", "title": "columns inside frames"}, {"id": "015285f2-680f-47fb-af19-9f045d1fec91", "type": "concept", "title": "overset text warnings"}], "description": "Students learn how text behaves inside InDesign and how threaded frames support multi-page reading."}, {"id": "54f3416c-18af-446b-8850-dc91acdb0b5c", "type": "subtopic", "title": "Image placement and fitting", "children": [{"id": "7d473197-42ef-4e38-999e-672b4592b339", "type": "concept", "title": "frame fitting options"}, {"id": "013303e8-00fe-4590-80cf-48af86d2a99c", "type": "concept", "title": "content-aware fit"}, {"id": "088035a1-6d7d-439d-a178-6b816c08f423", "type": "concept", "title": "effective resolution"}, {"id": "e8e9998c-1ca3-4ab2-bf75-abd852a1e55d", "type": "concept", "title": "captions and credit lines"}], "description": "Students learn to place, crop, scale, and align images without damaging quality or breaking links."}, {"id": "6a8e4537-16a4-44f1-8bbe-d60e931f7b55", "type": "subtopic", "title": "Objects, layers, and alignment", "children": [{"id": "bf91520d-4037-45de-9ea6-8aafed1083fb", "type": "concept", "title": "object stacking"}, {"id": "74c0e22a-d2e1-4483-8d36-1d31fa86ba09", "type": "concept", "title": "alignment tools"}, {"id": "76df6575-712d-4cc0-a100-ee38ee0a72fd", "type": "concept", "title": "text wrap"}, {"id": "926f53ca-4a46-4286-b858-6b97f40deb2b", "type": "concept", "title": "layer naming and locking"}], "description": "Students manage shapes, rules, objects, and layers so layouts stay editable and orderly."}]}, {"id": "ae09951c-7cd1-4339-93d6-284d8bb4ada1", "type": "topic", "title": "Typography for Layout: Hierarchy, Readability, Styles, and Long-Form Text", "description": "Typography is the spine of page layout. Students develop type judgment for headlines, bodies, captions, tables, and long-form editorial systems.", "children": [{"id": "4afeb1ed-e0f4-4e30-983b-161f17354e23", "type": "subtopic", "title": "Type hierarchy and voice", "children": [{"id": "5242fbde-535c-4433-aaf9-f40e93633db2", "type": "concept", "title": "display, text, and utility faces"}, {"id": "c2c995a5-445d-4484-ada2-0af930417ad9", "type": "concept", "title": "type pairing"}, {"id": "b8c4816e-2a61-4573-992e-6597a6d92559", "type": "concept", "title": "scale systems"}, {"id": "7a9a02a4-2c2d-4323-8feb-23702f07b9bc", "type": "concept", "title": "typographic contrast"}], "description": "Students learn to choose and combine typefaces so the publication has a clear tone and a readable order."}, {"id": "3f7f42f2-f13c-4481-98a7-cb312565175e", "type": "subtopic", "title": "Readability and spacing", "children": [{"id": "73f4f5f9-f68b-4806-a65c-186010679824", "type": "concept", "title": "leading, tracking, and kerning"}, {"id": "a1193e3c-5bd1-462f-95eb-c27b54d73d4e", "type": "concept", "title": "measure and line length"}, {"id": "9d1b7c06-3e08-4d18-b56a-95f8d25c3077", "type": "concept", "title": "paragraph spacing"}, {"id": "b83e26bf-c1f2-4f25-80de-8739d00dfee5", "type": "concept", "title": "widows, orphans, and rivers"}], "description": "Students tune type so reading feels effortless across short and long documents."}, {"id": "165c4a31-5012-4e0e-a5fb-7c61b7863bad", "type": "subtopic", "title": "Long-form text systems", "children": [{"id": "9fbc9585-b06d-4172-b4ce-941a5625f88f", "type": "concept", "title": "threaded stories"}, {"id": "b73edf36-8819-4677-b8ce-cffac59f9e0a", "type": "concept", "title": "columns and text flow"}, {"id": "dc65933c-90b5-4deb-9238-1bc92d3ea4df", "type": "concept", "title": "hyphenation and justification"}, {"id": "e04e3c9a-5387-4dea-96e9-70ca53e6a5b6", "type": "concept", "title": "footnotes, endnotes, and running headers"}], "description": "Students learn the features that make books, reports, and magazines manageable."}]}, {"id": "ce8a362d-6c73-4726-8ee7-df25af6c8669", "type": "topic", "title": "Paragraph, Character, Object, Table, and Master/Parent Page Styles", "description": "Styles are the bridge between design and production. Students learn to make documents consistent, fast to revise, and easier to hand off.", "children": [{"id": "59d06136-3117-4b59-bbbb-3646818ad635", "type": "subtopic", "title": "Paragraph and character styles", "children": [{"id": "6fa68e9b-eb70-41f4-98d6-7ce427db4ace", "type": "concept", "title": "style hierarchy"}, {"id": "9ab82079-2a30-424e-9895-43ff0613eab8", "type": "concept", "title": "nested and GREP styles"}, {"id": "363e9ab1-1768-4cbb-9f52-7385dab82504", "type": "concept", "title": "based-on relationships"}, {"id": "696190f9-d607-45c6-bb43-624c9af137f3", "type": "concept", "title": "style overrides and cleanup"}], "description": "Students create reusable type rules so formatting is systematic instead of manual."}, {"id": "e72fafde-3761-42e0-82c5-63ec5f85f130", "type": "subtopic", "title": "Object, table, and cell styles", "children": [{"id": "188977ad-1eea-44e9-95b3-432adb759a7d", "type": "concept", "title": "object style defaults"}, {"id": "b6590a35-c211-4d71-b116-2e7b676faf5b", "type": "concept", "title": "table headers and body cells"}, {"id": "78ee8847-8347-4ecb-80c3-3da0b7a52f36", "type": "concept", "title": "caption frames"}, {"id": "c3c8e4c2-dced-4561-affb-989710e760f7", "type": "concept", "title": "rule and callout styling"}], "description": "Students extend consistency beyond type into frames, tables, rules, and recurring page elements."}, {"id": "45dfce12-1deb-4526-a3ac-85cb7e13d996", "type": "subtopic", "title": "Parent pages and master systems", "children": [{"id": "99ede377-8e6b-4731-8a40-b64fec2e7082", "type": "concept", "title": "folios and running heads"}, {"id": "c5f1a9b0-4202-481f-b3cf-281086fa3413", "type": "concept", "title": "section markers"}, {"id": "2c070496-d92e-4af1-ab8b-70fce4f4538e", "type": "concept", "title": "automatic page numbering"}, {"id": "30be43cd-a624-40ef-b451-1aada11afe0e", "type": "concept", "title": "parent page overrides"}], "description": "Students learn how recurring layout elements control page identity while allowing local variation."}]}, {"id": "4abef52a-e3bf-47ab-8401-405138d21251", "type": "topic", "title": "Image Preparation, Resolution, Color Modes, and Linked Asset Management", "description": "Strong layout depends on production-ready images. Students learn how resolution, color, compression, and file linking affect final output quality.", "children": [{"id": "32b64ba0-27c0-4ddc-b6c5-1f1f5dc38361", "type": "subtopic", "title": "Raster image preparation", "children": [{"id": "064a6b8c-77c2-4549-863c-6aa29890f530", "type": "concept", "title": "ppi and effective resolution"}, {"id": "a4d0f09b-51f3-4240-8434-0427ab3cd541", "type": "concept", "title": "cropping and sharpening"}, {"id": "bf8f5723-c25d-4759-8412-d976a464c7f1", "type": "concept", "title": "retouching boundaries"}, {"id": "1d426f82-4b64-423c-aa91-3ade7e18ec5e", "type": "concept", "title": "PSD, TIFF, JPEG, and PNG choices"}], "description": "Students learn the Photoshop-facing skills needed to deliver clean, correctly sized imagery."}, {"id": "57b8d3d2-5f70-45c3-a71b-b4cc90c6e6c1", "type": "subtopic", "title": "Vector and illustration assets", "children": [{"id": "3da52a03-d2a9-4985-a420-58433e5fac71", "type": "concept", "title": "AI and PDF placement"}, {"id": "9bf8dbe1-59d0-4376-b8a9-64f015b5b942", "type": "concept", "title": "logos and icons"}, {"id": "d9c6b32f-9065-4c33-82c3-ecf4dd7a922a", "type": "concept", "title": "spot colors and swatches"}, {"id": "2a179dbc-0486-4eeb-b0d4-26fc85570ad7", "type": "concept", "title": "scalable diagrams"}], "description": "Students learn when Illustrator assets should remain vector and how to import them without losing editability or clarity."}, {"id": "8b9aa7b6-dec2-439d-ad5c-44235098854d", "type": "subtopic", "title": "Color management and asset integrity", "children": [{"id": "5d618e51-83db-4d7d-aa0d-bc6a676d7674", "type": "concept", "title": "RGB, CMYK, and spot color"}, {"id": "c4ddcbb1-3afe-44e5-aaac-13dc9fbc6c4a", "type": "concept", "title": "ICC profiles"}, {"id": "f60ea2c0-7c07-40aa-82a3-fb543628aa93", "type": "concept", "title": "link relinking and updates"}, {"id": "8cc01e93-3b77-4b30-85d8-4733fbd04f50", "type": "concept", "title": "missing fonts and missing links"}], "description": "Students learn how profiles, swatches, and links protect color and quality through the production chain."}]}, {"id": "67c5eb9a-3c91-4c2f-934b-b2958ac9ec62", "type": "topic", "title": "Multi-Page Editorial Design: Covers, TOCs, Sections, and Navigation", "description": "Students move from individual pages to full publications. The focus is pacing, navigation, and consistency across covers, front matter, sections, and endings.", "children": [{"id": "6f5ba902-b14f-45ad-811e-a37ca1df0f99", "type": "subtopic", "title": "Publication architecture", "children": [{"id": "db2031cb-e273-4c85-9252-50a0de56ebe1", "type": "concept", "title": "cover and back cover roles"}, {"id": "ac857edf-3b73-4f60-a266-06c5bdfba7bf", "type": "concept", "title": "front matter"}, {"id": "873181cd-96b2-47dd-ba35-8e68aa9ada83", "type": "concept", "title": "table of contents"}, {"id": "72281726-e676-4920-88db-71eb8190702f", "type": "concept", "title": "section openers and departments"}], "description": "Students plan how readers enter, move through, and leave a publication."}, {"id": "dbea6feb-5787-416c-a5e9-dee967e24f42", "type": "subtopic", "title": "Editorial pacing", "children":